async function selectPreset(id,{internalReplay=false}={}){if(!internalReplay&&(entryOperation||entryCancellation))await cancelMainEntry();if(!ALL_PRESETS.some(p=>p.id===id))throw Error('未知人物预设');if(!internalReplay){invalidateEntryRequest('正在应用所选人物预设');presetTicket++;}pendingPreset=id;presetBrowser.setBusy(id);if(!controller||(busy&&!internalReplay)){if(!busy)await load();return;}const ticket=++presetTicket;await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(ticket!==presetTicket||!active||!controller)return;panel?.cancelEdits();const start=performance.now();try{const previous=controller.presetId===id?null:controller.archive();controller.applyPreset(id);if(previous)previousPresetArchive=previous;presetSwitchMS=performance.now()-start;viewPerson('three');pendingPreset=null;presetBrowser.sync(controller);}catch(e){status('预设切换失败：'+e.message);presetBrowser.sync(controller);throw e;}}
