function cancelMainEntry(){if(entryCancellation)return entryCancellation;const pending=entryOperation,prior=entryRestoreArchive;pendingPreset=null;invalidateEntryRequest();const ticket=entryTicket;entryBusy=true;entryCancelling=true;syncEntryControls();entryCancellation=(async()=>{await Promise.resolve();try{if(busy){release();entryMessage('已取消载入，可以重新点击擂台或人物。');return;}if(motionStudio)await motionStudio.setMode('shape');if(pending)await pending.catch(()=>{});if(active&&ticket===entryTicket&&(!motionStudio||motionStudio.mode==='shape')){if(prior)controller?.restore(prior);viewer?.view('three');entryMessage('已取消场景准备，恢复原人物，可以重试。');}}finally{entryCancellation=null;entryCancelling=false;if(active&&ticket===entryTicket){entryBusy=false;entryRestoreArchive=null;}syncEntryControls();}})();return entryCancellation;}

async function activateMainEntry(key){const intent=ENTRY_ACTIONS[key];if(!intent)throw new RangeError('未知总台入口');return withEntryRequest(intent.label,async isCurrent=>{if(key==='shape'){if(motionStudio)await motionStudio.setMode('shape');if(!isCurrent())return{applied:false};viewer.view('face');entryMessage('人物 / 五官：在原三维头身上切换上方身份，右侧体格与原参数仍保留。');return{applied:true,mode:'shape'};}const studio=motionStudio;const result=await activateEntryIntent(studio,key,{isCurrent:()=>isCurrent()&&studio===motionStudio&&!studio?.destroyed});if(result.applied)entryMessage(intent.label+' · 已进入原有模式并开始播放。实现范围请看画面下方说明。');return result;});}
async function selectFaceIdentity(id){const choice=FACE_IDENTITIES.find(x=>x.id===id);if(!choice)throw new RangeError('未知五官身份');return withEntryRequest(choice.label,async isCurrent=>{const studio=motionStudio;if(studio)await studio.setMode('shape');if(!isCurrent()||studio!==motionStudio)return{applied:false};pendingPreset=null;presetTicket++;panel?.cancelEdits();const original=controller.archive(),state=controller.state();if(state.headShapeComposition!=='shared-layers/1'&&state.owners.headShape!=='gnm')throw Error('当前头形由其他来源独占；请先在原参数里选择共同叠加或GNM头形。');const next=applyFaceIdentity(state,id,{headOnlyAnnyLocalLabels:controller.model.headTransfer?.headOnlyAnnyLocalLabels});applyingFace=true;try{controller.commit(next);previousFaceArchive=original;faceSelection=id;}finally{applyingFace=false;}presetBrowser.sync(controller);viewer.view('face');syncEntryControls();entryMessage(choice.label+' · 原生GNM身份已应用；保留身体参数，混合头身局部不被清除。');return{applied:true,id};});}
